import { useState } from "react";
import { Meta, StoryObj } from "@storybook/react";
import FullPageOverlay from "./full-page-overlay";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { expect, userEvent, within } from "storybook/test";
import { desktopOnlyMode } from "../../../../.storybook/preview";
import { ContentContainer } from "@/core/components/primitives/content-container/content-container";

const meta = {
  title: "Primitives/Full Page Overlay",
  component: FullPageOverlay,
  parameters: {
    layout: "fullscreen",
  },
} satisfies Meta<typeof FullPageOverlay>;

export default meta;

type Story = StoryObj<typeof meta>;

const BUTTON_TEXT = "Show";
const HEADLINE = "Some nice content";

export const Primary: Omit<Story, "args"> = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    const button = canvas.getByText(BUTTON_TEXT);
    userEvent.click(button);

    //Wait for 1 seconds to make sure the animation is done
    await new Promise((resolve) => setTimeout(resolve, 1000));

    await expect(canvas.getByText(HEADLINE)).toBeInTheDocument();
    await expect(canvas.getByTestId("fullPageOverlayCloseButton")).toBeInTheDocument();
  },
  render: function PrimaryStory(args) {
    const [isOpen, setIsOpen] = useState(false);

    return (
      <ContentContainer>
        <div>
          <PrimaryButton
            label={BUTTON_TEXT}
            onClick={() => {
              setIsOpen(true);
            }}
          />
          <FullPageOverlay
            {...args}
            open={isOpen}
            onClose={() => {
              setIsOpen(false);
            }}
          >
            <div style={{ margin: "2rem" }}>
              <h1>{HEADLINE}</h1>
              <p>Very nice content</p>
            </div>
          </FullPageOverlay>
        </div>
      </ContentContainer>
    );
  },
};

export const VerticalScroll: Omit<Story, "args"> = {
  parameters: {
    chromatic: desktopOnlyMode,
  },
  render: function PrimaryStory(args) {
    const [isOpen, setIsOpen] = useState(false);

    const content = <p>Very nice content</p>;

    return (
      <ContentContainer>
        <div>
          <PrimaryButton
            label={BUTTON_TEXT}
            onClick={() => {
              setIsOpen(true);
            }}
          />
          <FullPageOverlay
            {...args}
            open={isOpen}
            onClose={() => {
              setIsOpen(false);
            }}
          >
            <div style={{ margin: "2rem" }}>
              <h1>{HEADLINE}</h1>
              {/* Repeat content 50 times to force vertical scroll */}
              {[...Array(50)].map((_, i) => (
                <div key={i}>{content}</div>
              ))}
            </div>
          </FullPageOverlay>
        </div>
      </ContentContainer>
    );
  },
};
