import { EventAggregator } from "@/core/helpers";
import { useLayoutEffect, useMemo, useState } from "react";

export const defaultBreakpoints = {
  DEVICE_MOBILE: 0,
  DEVICE_DESKTOP: 768,
} as const;

/**
 * @deprecated This hook is outdated. Use useCurrentBreakpoints instead,
 *  so that we always base our code on the defined breakpoints.
 */
export function useWindowWidthBreakpoints<Breakpoints extends string = keyof typeof defaultBreakpoints>(
  breakpoints: Record<Breakpoints, number> = defaultBreakpoints as Record<Breakpoints, number>,
): Breakpoints {
  const breakpointsString = JSON.stringify(breakpoints); // We stringify the breakpoints object to avoid unnecessary re-renders
  const sortedBreakpoints = useMemo(() => {
    const pairs = Object.entries(JSON.parse(breakpointsString)) as Array<[Breakpoints, number]>;
    return pairs.sort(([, aWidth], [, bWidth]) => aWidth - bWidth);
  }, [breakpointsString]);

  const [currentBreakpoint, setCurrentBreakpoint] = useState(sortedBreakpoints[0][0]);

  useLayoutEffect(() => {
    const widthUpdated = (width: number) => {
      const [breakpoint] =
        sortedBreakpoints.findLast(([, breakpointWidth]) => width >= breakpointWidth) ?? sortedBreakpoints[0];

      if (breakpoint !== currentBreakpoint) setCurrentBreakpoint(breakpoint);
    };
    const onResizeWindowWidthSubscription = EventAggregator.subscribe("onResizeWindowWidth", widthUpdated);

    if (typeof window !== "undefined") widthUpdated(window.innerWidth);

    return () => {
      onResizeWindowWidthSubscription.remove();
    };
  }, [sortedBreakpoints, currentBreakpoint]);

  return currentBreakpoint;
}
